import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import reportWebVitals from './reportWebVitals';
import { BrowserRouter as Router, Route, Routes, Link, Navigate } from 'react-router-dom';
import SignInForm from './pages/SignInForm/SignInForm';
import SignUpForm from './pages/SignUpForm/SignUpForm';
import CoachSignInForm from './pages/CoachSignInForm/CoachSignInForm';
import CoachSignUpForm from './pages/CoachSignUpForm/CoachSignUpForm';
import Dashboard from './pages/Dashboard/Dashboard';
import Home from './pages/Home/Home';
import './App.css';

const AppWrapper = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(!!localStorage.getItem('coachToken'));
  const [isUserAuthenticated, setIsUserAuthenticated] = useState(!!localStorage.getItem('userToken'));
  const [isLoading, setIsLoading] = useState(true);

  // Check authentication status
  const checkAuth = () => {
    const coachAuth = !!localStorage.getItem('coachToken');
    const userAuth = !!localStorage.getItem('userToken');
    setIsAuthenticated(coachAuth);
    setIsUserAuthenticated(userAuth);
    setIsLoading(false);
    return coachAuth || userAuth;
  };

  useEffect(() => {
    // Initial auth check
    checkAuth();

    // Custom storage event handler for cross-tab sync
    const handleStorageChange = (e) => {
      if (e.key === 'coachToken' || e.key === 'userToken') {
        checkAuth();
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  // Handle successful login
  const handleCoachLogin = () => {
    localStorage.setItem('coachToken', 'true'); // Actual token would be set in SignInForm
    checkAuth();
  };

  const handleUserLogin = () => {
    localStorage.setItem('userToken', 'true');
    checkAuth();
  };

  // Handle logout
  const handleLogout = () => {
    localStorage.removeItem('coachToken');
    localStorage.removeItem('userToken');
    localStorage.removeItem('coachName');
    checkAuth();
  };

  if (isLoading) {
    return <div className="loading-screen">Loading...</div>;
  }

  return (
    <Router>
      <div className="App">
        {/* Navbar */}
        <header className="app-header">
          <nav className="navbar">
            <h1>Fitness Management</h1>
            <ul>
              <li><Link to="/" className="nav-link">Home</Link></li>
              {!isAuthenticated && !isUserAuthenticated ? (
                <>
                  <li><Link to="/signin" className="nav-link">User Sign In</Link></li>
                  <li><Link to="/signup" className="nav-link">User Sign Up</Link></li>
                  <li><Link to="/coach/signin" className="nav-link">Coach Sign In</Link></li>
                  <li><Link to="/coach/signup" className="nav-link">Coach Sign Up</Link></li>
                </>
              ) : isAuthenticated ? (
                <li><Link to="/dashboard" className="nav-link">Dashboard</Link></li>
              ) : null}
            </ul>
          </nav>
        </header>

        {/* Page Routing */}
        <main className="main-content">
          <Routes>
            <Route path="/" element={<Home />} />
            {/* User routes */}
            <Route 
              path="/signin" 
              element={
                isUserAuthenticated || isAuthenticated ? (
                  <Navigate to="/" replace />
                ) : (
                  <SignInForm onLogin={handleUserLogin} />
                )
              } 
            />
            <Route 
              path="/signup" 
              element={
                isUserAuthenticated || isAuthenticated ? (
                  <Navigate to="/" replace />
                ) : (
                  <SignUpForm onSignup={handleUserLogin} />
                )
              } 
            />
            {/* Coach routes */}
            <Route 
              path="/coach/signin" 
              element={
                isAuthenticated ? (
                  <Navigate to="/dashboard" replace />
                ) : (
                  <CoachSignInForm onLogin={handleCoachLogin} />
                )
              } 
            />
            <Route 
              path="/coach/signup" 
              element={
                isAuthenticated ? (
                  <Navigate to="/dashboard" replace />
                ) : (
                  <CoachSignUpForm onSignup={handleCoachLogin} />
                )
              } 
            />
            <Route 
              path="/dashboard" 
              element={
                isAuthenticated ? (
                  <Dashboard onLogout={handleLogout} />
                ) : (
                  <Navigate to="/coach/signin" replace />
                )
              } 
            />
          </Routes>
        </main>

        {/* Footer */}
        <footer className="footer">
          <p>&copy; 2025 Fitness Management. All rights reserved.</p>
        </footer>
      </div>
    </Router>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <AppWrapper />
  </React.StrictMode>
);

reportWebVitals();
